SELECT o.channel, CASE WHEN o.amount >= 1700 THEN 'high' WHEN o.amount >= 510 THEN 'mid' ELSE 'low' END AS amount_bucket, ROUND((100 * SUM(CASE WHEN p.status = 'REFUNDED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_refunded FROM payments p JOIN orders o ON o.id = p.order_id WHERE o.channel NOT IN ('store', 'web') GROUP BY o.channel, CASE WHEN o.amount >= 1700 THEN 'high' WHEN o.amount >= 510 THEN 'mid' ELSE 'low' END ORDER BY pct_refunded DESC
